SELECT COUNT(DISTINCT CO_ENTIDADE) AS Número_de_escolas_com_QT_MAT_BAS_igual_a_zero
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT COUNT(DISTINCT CO_ENTIDADE) AS TOTAL_SCOOL
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT CO_ENTIDADE
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT CO_ENTIDADE, COUNT(DISTINCT CO_ENTIDADE) AS total_publica, COUNT(DISTINCT CO_ENTIDADE) - COUNT(DISTINCT CO_ENTIDADE) AS total_privada
FROM matriculas
GROUP BY CO_ENTIDADE;

SELECT DICIONARIO: NOME_VARIAVEL 
FROM matriculas 
WHERE TP_CATEGORIA_ESCOLA_PRIVADA = 'Particular';

SELECT DICIONARIO: NOME_VARIAVEL 
FROM matriculas 
WHERE TP_CATEGORIA_ESCOLA_PRIVADA = 'Comunitária';

SELECT DICIONARIO: NOME_VARIAVEL 
FROM matriculas 
WHERE TP_CATEGORIA_ESCOLA_PRIVADA = 'Confessional';

SELECT DICIONARIO: NOME_VARIAVEL 
FROM matriculas 
WHERE TP_CATEGORIA_ESCOLA_PRIVADA = 'Filantrópica';

SELECT COUNT(DISTINCT CO_ENTIDADE) AS total_escolas_urbanas, COUNT(DISTINCT CO_ENTIDADE) AS total_escolas_rurais
FROM matriculas
WHERE TP_LOCALIZACAO = '2' OR TP_LOCALIZACAO = '3';

SELECT COUNT(DISTINCT CO_ENTIDADE) AS escolas_urbanas, COUNT(DISTINCT CO_ENTIDADE) AS escolas_rurais
FROM matriculas
WHERE TP_LOCALIZACAO = '2';

SELECT SUM(CASE WHEN TP_LOCALIZACAO = '2' THEN QT_MAT_BAS END) AS total_escolas_urbanas,
       SUM(CASE WHEN TP_LOCALIZACAO = '1' THEN QT_MAT_BAS END) AS total_escolas_rurais
FROM matriculas;

SELECT AVG(SUM(QT_MAT_BAS)) AS media_urbana
FROM matriculas
WHERE TRIM(SG_UF) <> '' AND TP_LOCALIZACAO = '2';

SELECT AVG(SUM(QT_MAT_BAS)) AS media_rural
FROM matriculas
WHERE TRIM(SG_UF) <> '' AND TP_LOCALIZACAO = '1';

SELECT SUM(QT_MAT_BAS) AS total_matrículas_ND
FROM matriculas
WHERE QT_MAT_BAS_ND IS NOT NULL;

SELECT SUM(QT_MAT_BAS) AS total_matrículas_ND
FROM matriculas
WHERE QT_MAT_BAS_ND IS NOT NULL AND QT_MAT_BAS_ND <> 0;

SELECT SUM(QT_MAT_BAS) AS total_matrículas_diurno
FROM matriculas
WHERE TRIM(TP_LOCALIZACAO) = '2' AND TRIM(TP_LOCALIZACAO_DIFERENCIADA) = '1';

SELECT SUM(QT_MAT_BAS) AS total_matrículas_matutino
FROM matriculas
WHERE TRIM(TP_LOCALIZACAO) = '1' AND TRIM(TP_LOCALIZACAO_DIFERENCIADA) = '1';

SELECT SUM(QT_MAT_BAS) AS total_matrículas_vespertino
FROM matriculas
WHERE TRIM(TP_LOCALIZACAO) = '2' AND TRIM(TP_LOCALIZACAO_DIFERENCIADA) = '2';
